toolArgs.file_text:
@namespace sv_3cc2f5e6dd8f4ef39fbaedd5e0841251.Components.Pages.Settings
@using sv_3cc2f5e6dd8f4ef39fbaedd5e0841251.Services
@inject ISettingsService SettingsService

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <!-- Change Password -->
            <div class="mb-4">
                <div class="d-flex align-items-center mb-2">
                    <h6 class="mb-0">Change Password</h6>
                    <button class="btn btn-sm btn-outline-secondary ms-2" @onclick="() => _passwordExpanded = !_passwordExpanded">
                        @(_passwordExpanded ? "▲ Collapse" : "▼ Expand")
                    </button>
                </div>
                @if (_passwordExpanded)
                {
                    <div class="border rounded p-3">
                        <div class="mb-2">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-2">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                            @if (_changingPassword) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="mb-4">
                <h6>Two-Factor Authentication</h6>
                <div class="d-flex align-items-center gap-2">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor" checked="@_twoFactorEnabled" disabled />
                        <label class="form-check-label" for="twoFactor">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </label>
                    </div>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-warning")">
                        @(_twoFactorEnabled ? "✓ Active" : "⚠ Inactive")
                    </span>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <small class="text-muted">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</small>
                }
            </div>

            <!-- Active Sessions -->
            <div>
                <h6>Active Sessions</h6>
                @if (_sessions.Count == 0)
                {
                    <p class="text-muted">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-sm table-hover">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != _sessions.First())
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => ConfirmRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="badge bg-info">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5);">
                    <div class="modal-dialog modal-dialog-centered">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Confirm Session Revocation</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                            </div>
                            <div class="modal-footer">
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button class="btn btn-danger" @onclick="RevokeSessionAsync" disabled="@_revoking">
                                    @if (_revoking) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                    Revoke Session
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string? _message;
    private bool _messageIsError;

    // Password change
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;

    // Session revocation
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _message = null;
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "New password cannot be empty.";
            _messageIsError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _message = "New password and confirmation do not match.";
            _messageIsError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _message = "Password updated successfully!";
            _messageIsError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordExpanded = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to change password: {ex.Message}";
            _messageIsError = true;
        }
        _changingPassword = false;
    }

    private void ConfirmRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.Remove(_sessionToRevoke);
        _sessionToRevoke = null;
        _revoking = false;
        _message = "Session revoked.";
        _messageIsError = false;
    }
}

