@namespace sv_3cc2f5e6dd8f4ef39fbaedd5e0841251.Components.Pages.Settings
@using sv_3cc2f5e6dd8f4ef39fbaedd5e0841251.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance Settings</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-6">
                    <!-- Theme -->
                    <div class="mb-4">
                        <h6>Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    <!-- Font Size -->
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"size-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"size-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    <!-- Language -->
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>
                </div>

                <!-- Live Preview -->
                <div class="col-md-6">
                    <h6>Preview</h6>
                    <div class="border rounded p-3 @PreviewBackgroundClass" style="@PreviewStyle">
                        <h6 style="@PreviewFontStyle">Sample Heading</h6>
                        <p style="@PreviewFontStyle" class="@(PreviewTextClass)">
                            This is how your content will look with the selected appearance settings.
                        </p>
                        <div class="d-flex gap-2 @(_compactMode ? "my-1" : "my-3")">
                            <span class="badge bg-primary">Tag 1</span>
                            <span class="badge bg-secondary">Tag 2</span>
                            <span class="badge bg-success">Tag 3</span>
                        </div>
                        <button class="btn btn-sm btn-primary" disabled>Sample Button</button>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        }
    </div>
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string PreviewBackgroundClass => _theme switch
    {
        "Dark" => "bg-dark text-light",
        "Light" => "bg-white text-dark",
        _ => "bg-light text-dark"
    };

    private string PreviewTextClass => _compactMode ? "mb-1" : "mb-3";

    private string PreviewStyle => _theme == "Dark"
        ? "min-height:150px;border-color:#444 !important;"
        : "min-height:150px;";

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.25rem;",
        _ => "font-size:1rem;"
    };

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
        _saving = false;
    }
}

